.ndere-transcript{font-family:"Times New Roman",serif;font-size:9px;line-height:1.12;min-height:245mm;position:relative;box-sizing:border-box;padding:8mm 2mm 5mm}
.ndere-official{display:grid;grid-template-columns:1fr 1fr 1fr;align-items:start;text-align:center;gap:3mm;font-size:8px;line-height:1.25}
.ndere-official>div{min-width:0}.ndere-official strong{font-size:9px}.ndere-university img{display:block;height:13mm;max-width:20mm;object-fit:contain;margin:0 auto 1mm}
.ndere-school{text-align:center;font-size:8px;line-height:1.18;margin-top:2mm}.ndere-school strong{font-size:14px}
.ndere-title-row{display:grid;grid-template-columns:22% 56% 22%;align-items:center;text-align:center;margin:3mm 0 2mm;min-height:20mm}.ndere-title{font-size:10px;line-height:1.2}.ndere-title strong:last-child{font-size:12px}.ndere-side-logo img{display:block;max-height:17mm;max-width:18mm;object-fit:contain;margin:auto}.ndere-side-logo span{display:block;font-size:7px}
.ndere-identity{display:grid;grid-template-columns:1fr 1fr;gap:4mm;line-height:1.3;margin:3mm 1mm 3mm;font-size:9px}.ndere-identity>div{min-width:0;overflow-wrap:anywhere}
.ndere-marks{table-layout:fixed;width:100%;margin:0;font-size:8px}.ndere-marks th,.ndere-marks td{border:1px solid #222;padding:2px 3px;line-height:1.15;vertical-align:middle;background:#fff}.ndere-marks th{font-weight:bold}.ndere-marks .left{text-align:left}.ndere-code{width:10%}.ndere-course{width:28%}.ndere-mark{width:8%}.ndere-grade{width:10%}.ndere-credit{width:7%}.ndere-year{width:13%}.ndere-semester{width:10%}.ndere-observation{width:14%}.ndere-bilan th,.ndere-bilan td{border-top:2px solid #222}
.ndere-signatures{display:flex;justify-content:space-between;text-align:center;margin:16mm 5mm 0;min-height:30mm;font-size:9px}.ndere-signatures>div{width:40%}.ndere-signatures span{display:block;font-size:8px;margin-top:5mm}.ndere-note{font-size:8px;text-align:center;margin:12mm 0 0}
.paper-a3 .ndere-transcript{font-size:13px;min-height:355mm;padding:11mm 4mm}.paper-a3 .ndere-official,.paper-a3 .ndere-school,.paper-a3 .ndere-marks,.paper-a3 .ndere-note{font-size:11px}.paper-a3 .ndere-identity,.paper-a3 .ndere-signatures{font-size:12px}.paper-a3 .ndere-school strong{font-size:20px}.paper-a3 .ndere-title{font-size:14px}.paper-a3 .ndere-title strong:last-child{font-size:17px}
@media print{.modele-ngaoundere.document-releve .preview{display:none}.ndere-transcript{min-height:0;break-after:page;page-break-after:always}.ndere-transcript:last-of-type{break-after:auto;page-break-after:auto}.ndere-signatures{break-inside:avoid}.ndere-marks tr{break-inside:avoid}}
